(function(){var root=document.documentElement;root.classList.remove('no-js');try{var saved=localStorage.getItem('theme');if(saved==='light'||saved==='dark'){root.setAttribute('data-theme',saved);root.setAttribute('data-theme-mode',saved);}else{root.setAttribute('data-theme','dark');root.setAttribute('data-theme-mode','dark');}}catch(error){root.setAttribute('data-theme','dark');}})();